DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__RcdMigrationsHistory" WHERE "MigrationId" = '20260805181636_SubscriptionsAndAlerts') THEN
    CREATE TABLE rcd_alerts (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OwnerUserId" character varying(128) NOT NULL,
        "DashboardId" integer,
        "Name" character varying(128) NOT NULL,
        "SpecJson" jsonb NOT NULL,
        "Operator" character varying(8) NOT NULL,
        "Threshold" numeric(28,8) NOT NULL,
        "Recipients" character varying(2048) NOT NULL,
        "EveryMinutes" integer NOT NULL,
        "CooldownMinutes" integer NOT NULL,
        "Enabled" boolean NOT NULL,
        "LastEvaluatedUtc" timestamp without time zone,
        "LastFiredUtc" timestamp without time zone,
        "LastValue" numeric(28,8),
        "CreatedUtc" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_rcd_alerts" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

