        "DayOfWeekUtc" integer,
        "Recipients" character varying(2048) NOT NULL,
        "Format" character varying(8) NOT NULL,
        "Enabled" boolean NOT NULL,
        "LastRunUtc" timestamp without time zone,
        "CreatedUtc" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_rcd_subscriptions" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_rcd_subscriptions_rcd_dashboards_DashboardId" FOREIGN KEY ("DashboardId") REFERENCES rcd_dashboards ("Id") ON DELETE CASCADE
