        "CanEditCharts" boolean NOT NULL DEFAULT FALSE,
        "GrantedByUserId" character varying(128) NOT NULL,
        "CreatedAtUtc" timestamp without time zone NOT NULL,
        "UpdatedAtUtc" timestamp without time zone NOT NULL,
        CONSTRAINT "PK_rcd_dashboard_shares" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_rcd_dashboard_shares_rcd_dashboards_DashboardId" FOREIGN KEY ("DashboardId") REFERENCES rcd_dashboards ("Id") ON DELETE CASCADE
